import subprocess, re
txt=subprocess.check_output(['objdump','-d','orig']).decode(errors='ignore')
# extract func blocks
import re
funcs={}
cur=None; buf=[] 
for line in txt.splitlines():
    m=re.search(r'<(\w+)>:$', line)
    if m and ('Disassembly' not in line):
        if cur: funcs[cur]='\n'.join(buf)
        cur=m.group(1); buf=[line]
    elif cur:
        buf.append(line)
        if line.strip()=='ret' and len(buf)>20:
            # keep going? functions may have multiple rets; just continue until next func header; don't cut
            pass
if cur: funcs[cur]='\n'.join(buf)
for f in ['sky_color','is_in_shadow','trace','sphere_intersect','plane_intersect']:
    print('='*80)
    print(f)
    print(funcs[f][:12000])
